      "i": 5,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "हाँ है।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "कितनी piece चाहिए होगी आपको?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 10,
      "speaker": "caller",
      "text": "तीन हजार।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "चलिए अब width के बारे में बात कर लेते हैं।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "4 inch या कुछ और?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "हाँ four inch का nine into four into three है ना वही चाहिए।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "अब बताइए height में क्या prefer करेंगे?"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "3 inch, 4 inch या कोई और?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "regular size कपड़ा।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "regular size में आमतौर पर 3 inch या 4 inch होता है।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आप इनमें से क्या prefer करेंगे?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "9 into 4 into 3 बोलते ना उतना ही है।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है समझ गई।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "Okay."
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "Thank you."
    }
  ]
